  "BitCrusher": "program BitCrusher(\n  audio = 0,\n  bit_depth = 24,\n  sample_rate_hz = 44100\n) -> (output) {\n  reg hold_sample = 0\n  reg hold_counter = 0\n  output = let {\n      bd: clamp(bit_depth, 1, 24);\n      targetSr: clamp(sample_rate_hz, 1, sampleRate())\n    } in let {\n      levels: ldexp(1, bd - 1);\n      samplesPerHold: clamp(floorDiv(sampleRate(), targetSr), 1, 44100);\n      incremented: hold_counter + 1\n    } in let {\n      quantized: floorDiv(audio * levels + 0.5, 1) / levels;\n      shouldCapture: incremented >= samplesPerHold\n    } in select(shouldCapture, quantized, hold_sample)\n  next hold_sample = let {\n      bd: clamp(bit_depth, 1, 24);\n      targetSr: clamp(sample_rate_hz, 1, sampleRate())\n    } in let {\n      levels: ldexp(1, bd - 1);\n      samplesPerHold: clamp(floorDiv(sampleRate(), targetSr), 1, 44100);\n      incremented: hold_counter + 1\n    } in let {\n      quantized: floorDiv(audio * levels + 0.5, 1) / levels;\n      shouldCapture: incremented >= samplesPerHold\n    } in select(shouldCapture, quantized, hold_sample)\n  next hold_counter = let {\n      targetSr: clamp(sample_rate_hz, 1, sampleRate())\n    } in let {\n      samplesPerHold: clamp(floorDiv(sampleRate(), targetSr), 1, 44100);\n      incremented: hold_counter + 1\n    } in let {\n      shouldCapture: incremented >= samplesPerHold\n    } in select(shouldCapture, 0, incremented)\n}",
  "BlepSaw": "program BlepSaw(freq: freq = 440) -> (saw: signal) {\n  ph = Phasor(freq: freq)\n  saw = let {\n      inc: freq / sampleRate();\n      pw: ph.phase;\n      raw: 2 * pw - 1;\n      tp: pw / inc;\n      tpr: (pw - 1) / inc;\n      bpost: select(pw < inc, 2 * tp - tp * tp - 1, 0);\n      bpre: select(pw > 1 - inc, tpr * tpr + 2 * tpr + 1, 0)\n    } in raw - bpost - bpre\n}",
  "Bubble": "program Bubble(\n  trigger: signal = 0,\n  radius: float = 0.001,\n  q: float = 30,\n  sigma: float = 0.3,\n  decay_scale: float = 10,\n  amp_scale: float = 1,\n  attack_g: float = 0.05\n) -> (out: float) {\n  reg env_smooth = 0\n  hold = SampleHold(trigger: trigger, input: radius)\n  ramp = TriggerRamp(trigger: trigger)\n  decay_calc = Exp(\n    x: -1 / (sampleRate() * (decay_scale * hold.value + 0.000001)))\n  env_gen = EnvExpDecay(trigger: trigger, decay: decay_calc.out)\n  svf = SVF(\n    input: ramp.edge,\n    cutoff: let {\n        r_held: hold.value;\n        t_eff: ramp.frames\n      } in let {\n        tau: decay_scale * r_held + 0.000001;\n        f0: 3.26 / (r_held + 0.000001)\n      } in f0 * (1 + sigma * t_eff / (sampleRate() * tau)),\n    q: q)\n  out = env_smooth * svf.bp * (hold.value * 1000 * amp_scale)\n  next env_smooth = env_smooth + attack_g * (env_gen.env - env_smooth)\n}",
  "BubbleCloud": "program BubbleCloud(\n  trigger: signal = 0,\n  radius: float = 0.001,\n  q: float = 30,\n  sigma: float = 0.3,\n  decay_scale: float = 10,\n  amp_scale: float = 0.05\n) -> (out: float) {\n  reg voice_idx: int = 0\n  delay prev_trigger = trigger init 0\n  v0 = Bubble(trigger: trigger * (voice_idx == 0), radius: radius, q: q,\n    sigma: sigma, decay_scale: decay_scale, amp_scale: amp_scale)\n  v1 = Bubble(trigger: trigger * (voice_idx == 1), radius: radius, q: q,\n    sigma: sigma, decay_scale: decay_scale, amp_scale: amp_scale)\n  v2 = Bubble(trigger: trigger * (voice_idx == 2), radius: radius, q: q,\n    sigma: sigma, decay_scale: decay_scale, amp_scale: amp_scale)\n  v3 = Bubble(trigger: trigger * (voice_idx == 3), radius: radius, q: q,\n    sigma: sigma, decay_scale: decay_scale, amp_scale: amp_scale)\n  v4 = Bubble(trigger: trigger * (voice_idx == 4), radius: radius, q: q,\n    sigma: sigma, decay_scale: decay_scale, amp_scale: amp_scale)\n  v5 = Bubble(trigger: trigger * (voice_idx == 5), radius: radius, q: q,\n    sigma: sigma, decay_scale: decay_scale, amp_scale: amp_scale)\n  v6 = Bubble(trigger: trigger * (voice_idx == 6), radius: radius, q: q,\n    sigma: sigma, decay_scale: decay_scale, amp_scale: amp_scale)\n  v7 = Bubble(trigger: trigger * (voice_idx == 7), radius: radius, q: q,\n    sigma: sigma, decay_scale: decay_scale, amp_scale: amp_scale)\n  out = v0.out + v1.out + (v2.out + v3.out) +\n    (v4.out + v5.out + (v6.out + v7.out))\n  next voice_idx = let {\n      tick: (trigger > 0.5) * (prev_trigger <= 0.5)\n    } in (voice_idx + tick) % 8\n}",
  "Clock": "program Clock(\n  freq: freq = 1,\n  ratios_in: float[1] = [1]\n) -> (output: unipolar, ratios_out: float[1]) {\n  ph0 = Phasor(freq: freq)\n  ph1 = Phasor(freq: freq * ratios_in[0])\n  output = (ph0.phase < 0.5) * 1\n  ratios_out = [(ph1.phase < 0.5) * 1]\n}",
  "CombDelay": "program CombDelay(input: signal = 0, feedback: float = 0.7) -> (out: signal) {\n  reg s = 0\n  out = input + feedback * s\n  next s = input + feedback * s\n}",
