  "Delay": "program Delay<N: int = 44100>(x = 0) -> (y) breaks_cycles {\n  reg buf = zeros(N)\n  y = buf[sampleIndex() % N]\n  next buf = arraySet(buf, sampleIndex() % N, x)\n}",
  "EnvExpDecay": "program EnvExpDecay(\n  trigger: signal = 0,\n  decay: float = 0.999\n) -> (env: signal) {\n  enum Env { Idle, Decaying(level: float) }\n  delay prev_trigger = trigger init 0\n  delay state: Env = match state {\n      Idle => select(trigger > 0.5 && prev_trigger <= 0.5,\n        Decaying { level: 1 }, Idle { }),\n      Decaying { level: level } => select(\n        trigger > 0.5 && prev_trigger <= 0.5,\n        Decaying { level: 1 },\n        Decaying { level: level * decay })\n    } init Idle { }\n  env = match state { Idle => 0, Decaying { level: level } => level }\n}",
  "Exp": "program Exp(x: float = 0) -> (out: float) {\n  out = let {\n      clamped: clamp(x, -87, 88);\n      n: round(clamped * 1.4426950408889634);\n      r: clamped - n * 0.693145751953125 - n * 0.0000014286068203094173;\n      p: fold([0.000198756915, 0.0013981999507, 0.0083334519073,\n        0.041665795894, 0.16666665459, 0.50000001201],\n        0, (a, c) => c + a * r);\n      exp_r: 1 + r * (1 + r * p)\n    } in ldexp(exp_r, n)\n}",
  "LadderFilter": "program LadderFilter(\n  input = 0,\n  cutoff: freq = 1000,\n  resonance: unipolar = 0.5,\n  drive = 1\n) -> (lp, bp, hp, notch) {\n  delay prev_lp = pole4.out init 0\n  tanh_in = Tanh(x: drive * input)\n  sin_g = Sin(x: 3.141592653589793 *\n    (clamp(cutoff, 20, 0.49 * sampleRate()) / sampleRate()))\n  pole1 = OnePole(input: tanh_in.out - 4 * resonance * prev_lp,\n    g: 2 * sin_g.out)\n  pole2 = OnePole(input: pole1.out, g: 2 * sin_g.out)\n  pole3 = OnePole(input: pole2.out, g: 2 * sin_g.out)\n  pole4 = OnePole(input: pole3.out, g: 2 * sin_g.out)\n  lp = pole4.out\n  bp = pole2.out - pole4.out\n  hp = input - pole4.out\n  notch = input - pole4.out + pole4.out\n}",
  "Log": "program Log(x: float = 1) -> (out: float) {\n  out = let {\n      safe_x: select(x <= 0, 1e-45, x);\n      e0: floatExponent(safe_x);\n      m0: ldexp(safe_x, -e0);\n      is_big: m0 > 1.4142135623730951;\n      e: e0 + select(is_big, 1, 0);\n      m: select(is_big, m0 * 0.5, m0);\n      f: m - 1;\n      poly: fold([0.06666666666666667, -0.07142857142857142,\n        0.07692307692307693, -0.08333333333333333, 0.09090909090909091,\n        -0.1, 0.1111111111111111, -0.125, 0.14285714285714285,\n        -0.16666666666666666, 0.2, -0.25, 0.3333333333333333, -0.5, 1],\n        0, (a, c) => c + a * f)\n    } in f * poly + e * 0.6931471805599453\n}",
  "NoiseLFSR": "program NoiseLFSR(clock = 0) -> (out: signal) {\n  reg state: int = 44257\n  reg value = 0\n  delay prev_clock = clock init 0\n  out = let {\n      tick: (clock > 0.5) * (prev_clock <= 0.5);\n      lsb: state & 1;\n      shifted: state >> 1\n    } in let {\n      newState: select(lsb, shifted ^ 46080, shifted);\n      normalized: select(lsb, shifted ^ 46080, shifted) * 2 / 65535 - 1\n    } in select(tick, normalized, value)\n  next state = let {\n      tick: (clock > 0.5) * (prev_clock <= 0.5);\n      lsb: state & 1;\n      shifted: state >> 1\n    } in let {\n      newState: select(lsb, shifted ^ 46080, shifted)\n    } in select(tick, newState, state)\n  next value = let {\n      tick: (clock > 0.5) * (prev_clock <= 0.5);\n      lsb: state & 1;\n      shifted: state >> 1\n    } in let {\n      newState: select(lsb, shifted ^ 46080, shifted);\n      normalized: select(lsb, shifted ^ 46080, shifted) * 2 / 65535 - 1\n    } in select(tick, normalized, value)\n}",
  "OnePole": "program OnePole(input: signal = 0, g: float = 0.1) -> (out: signal) {\n  reg s = 0\n  tanh_in = Tanh(x: input)\n  tanh_s = Tanh(x: s)\n  out = s + g * (tanh_in.out - tanh_s.out)\n  next s = s + g * (tanh_in.out - tanh_s.out)\n}",
  "Phaser": "program Phaser<N: int = 4>(\n  input = 0,\n  feedback = 0.4,\n  lfo_speed = 0.2\n) -> (output, lfo) {\n  reg fb = 0\n  reg x_prev = zeros(N)\n  reg y_prev = zeros(N)\n  lfo_ph = Phasor(freq: lfo_speed)\n  lfo_sin = Sin(x: 6.283185307179586 * lfo_ph.phase)\n  output = let {\n    a: 0.6 + 0.35 * lfo_sin.out,\n    ys: scan(generate(N, (i) => i), input + feedback * fb, (acc, i) =>\n           -a * acc + x_prev[i] + a * y_prev[i])\n  } in 0.5 * input + 0.5 * ys[N - 1]\n  lfo = lfo_sin.out\n  next fb = let {\n    a: 0.6 + 0.35 * lfo_sin.out,\n    ys: scan(generate(N, (i) => i), input + feedback * fb, (acc, i) =>\n           -a * acc + x_prev[i] + a * y_prev[i])\n  } in ys[N - 1]\n  next y_prev = let { a: 0.6 + 0.35 * lfo_sin.out } in\n    scan(generate(N, (i) => i), input + feedback * fb, (acc, i) =>\n      -a * acc + x_prev[i] + a * y_prev[i])\n  next x_prev = let {\n    a: 0.6 + 0.35 * lfo_sin.out,\n    ys: scan(generate(N, (i) => i), input + feedback * fb, (acc, i) =>\n           -a * acc + x_prev[i] + a * y_prev[i])\n  } in generate(N, (i) =>\n    select(i > 0, ys[clamp(i - 1, 0, N - 1)], input + feedback * fb))\n}",
  "Phaser16": "program Phaser16(input = 0, feedback = 0.4, lfo_speed = 0.2) -> (output, lfo) {\n  reg fb = 0\n  program _allpassStage(x, a) -> (y) {\n    reg x_prev = 0\n    reg y_prev = 0\n    y = -a * x + x_prev + a * y_prev\n    next x_prev = x\n    next y_prev = -a * x + x_prev + a * y_prev\n  }\n  lfo_ph = Phasor(freq: lfo_speed)\n  lfo_sin = Sin(x: 6.283185307179586 * lfo_ph.phase)\n  ap_0 = _allpassStage(x: input + feedback * fb, a: 0.6 + 0.35 * lfo_sin.out)\n  ap_1 = _allpassStage(x: ap_0.y, a: 0.6 + 0.35 * lfo_sin.out)\n  ap_2 = _allpassStage(x: ap_1.y, a: 0.6 + 0.35 * lfo_sin.out)\n  ap_3 = _allpassStage(x: ap_2.y, a: 0.6 + 0.35 * lfo_sin.out)\n  ap_4 = _allpassStage(x: ap_3.y, a: 0.6 + 0.35 * lfo_sin.out)\n  ap_5 = _allpassStage(x: ap_4.y, a: 0.6 + 0.35 * lfo_sin.out)\n  ap_6 = _allpassStage(x: ap_5.y, a: 0.6 + 0.35 * lfo_sin.out)\n  ap_7 = _allpassStage(x: ap_6.y, a: 0.6 + 0.35 * lfo_sin.out)\n  ap_8 = _allpassStage(x: ap_7.y, a: 0.6 + 0.35 * lfo_sin.out)\n  ap_9 = _allpassStage(x: ap_8.y, a: 0.6 + 0.35 * lfo_sin.out)\n  ap_10 = _allpassStage(x: ap_9.y, a: 0.6 + 0.35 * lfo_sin.out)\n  ap_11 = _allpassStage(x: ap_10.y, a: 0.6 + 0.35 * lfo_sin.out)\n  ap_12 = _allpassStage(x: ap_11.y, a: 0.6 + 0.35 * lfo_sin.out)\n  ap_13 = _allpassStage(x: ap_12.y, a: 0.6 + 0.35 * lfo_sin.out)\n  ap_14 = _allpassStage(x: ap_13.y, a: 0.6 + 0.35 * lfo_sin.out)\n  ap_15 = _allpassStage(x: ap_14.y, a: 0.6 + 0.35 * lfo_sin.out)\n  output = 0.5 * input + 0.5 * ap_15.y\n  lfo = lfo_sin.out\n  next fb = ap_15.y\n}",
  "Phasor": "program Phasor(freq: freq = 440) -> (phase: unipolar) {\n  reg p = 0\n  phase = p\n  next p = (p + freq / sampleRate()) % 1\n}",
  "PoissonEvent": "program PoissonEvent(rate: float = 4) -> (trigger: signal) {\n  reg state: int = 2685821657736339000\n  trigger = let { s1: state ^ state << 13 } in\n    let { s2: s1 ^ s1 >> 7 } in\n    let { s3: s2 ^ s2 << 17 } in\n    let {\n      noise: (s3 & 65535) * 2 / 65535 - 1;\n      threshold: 1 - 2 * rate / sampleRate()\n    } in (noise > threshold) * 1\n  next state = let { s1: state ^ state << 13 } in\n    let { s2: s1 ^ s1 >> 7 } in s2 ^ s2 << 17\n}",
  "Pow": "program Pow(x: float = 1, y: float = 1) -> (out: float) {\n  log_x = Log(x: x)\n  exp = Exp(x: y * log_x.out)\n  out = exp.out\n}",
