  "SVF": "program SVF(\n  input: signal = 0,\n  cutoff: freq = 1000,\n  q: float = 0.707\n) -> (lp: signal, bp: signal, hp: signal) {\n  reg ic1eq = 0\n  reg ic2eq = 0\n  lp = let { g: 3.141592653589793 * cutoff / sampleRate(); k: 1 / q } in\n    let { a1: 1 / (1 + g * (g + k)) } in\n    let { a2: g * a1 } in\n    let { a3: g * a2; v3: input - ic2eq } in\n    let { v1: a1 * ic1eq + a2 * v3 } in\n    ic2eq + (a2 * ic1eq + a3 * v3)\n  bp = let { g: 3.141592653589793 * cutoff / sampleRate(); k: 1 / q } in\n    let { a1: 1 / (1 + g * (g + k)) } in\n    let { a2: g * a1; v3: input - ic2eq } in\n    a1 * ic1eq + a2 * v3\n  hp = let { g: 3.141592653589793 * cutoff / sampleRate(); k: 1 / q } in\n    let { a1: 1 / (1 + g * (g + k)) } in\n    let { a2: g * a1; a3: g * (g * a1); v3: input - ic2eq } in\n    let { v1: a1 * ic1eq + a2 * v3; v2: ic2eq + (a2 * ic1eq + a3 * v3) } in\n    input - k * v1 - v2\n  next ic1eq = let { g: 3.141592653589793 * cutoff / sampleRate(); k: 1 / q } in\n    let { a1: 1 / (1 + g * (g + k)) } in\n    let { a2: g * a1; v3: input - ic2eq } in\n    let { v1: a1 * ic1eq + a2 * v3 } in\n    2 * v1 - ic1eq\n  next ic2eq = let { g: 3.141592653589793 * cutoff / sampleRate(); k: 1 / q } in\n    let { a1: 1 / (1 + g * (g + k)) } in\n    let { a2: g * a1; a3: g * (g * a1); v3: input - ic2eq } in\n    let { v2: ic2eq + (a2 * ic1eq + a3 * v3) } in\n    2 * v2 - ic2eq\n}",
