  "Seq4MinorTranspose": "program Seq4MinorTranspose(trigger: unipolar = 0) -> (freq: freq) {\n  seq = Sequencer<N=4>(clock: trigger, values: [110, 130.81, 164.81, 196])\n  freq = seq.value\n}",
