  "Sin": "program Sin(x: float = 0) -> (out: float) {\n  out = let {\n      n: round(x * 0.3183098861837907);\n      r: x - n * 3.141592653589793;\n      odd_n: n & 1;\n      sign: 1 - 2 * odd_n;\n      r2: r * r;\n      poly: fold([-2.505210838544172e-8, 0.0000027557319223985893,\n        -0.0001984126984126984, 0.008333333333333333,\n        -0.16666666666666666, 1], 0, (a, c) => c + a * r2)\n    } in sign * (r * poly)\n}",
  "SinOsc": "program SinOsc(freq: freq = 440) -> (sine: float) {\n  ph = Phasor(freq: freq)\n  sin = Sin(x: 6.283185307179586 * ph.phase)\n  sine = sin.out\n}",
  "SoftClip": "program SoftClip(input: signal = 0, drive: float = 1) -> (out: signal) {\n  tanh = Tanh(x: drive * input)\n  out = tanh.out\n}",
  "Tanh": "program Tanh(x: float = 0) -> (out: float) {\n  out = let { c: clamp(x, -3, 3); c2: c * c } in c * (27 + c2) / (27 + 9 * c2)\n}",
  "TriggerRamp": "program TriggerRamp(trigger: signal = 0) -> (frames: float, edge: float) {\n  enum RampState { Quiescent, Counting(n: int) }\n  delay prev_trigger = trigger init 0\n  delay state: RampState = match state {\n      Quiescent => select(trigger > 0.5 && prev_trigger <= 0.5,\n        Counting { n: 0 }, Quiescent { }),\n      Counting { n: n } => select(trigger > 0.5 && prev_trigger <= 0.5,\n        Counting { n: 0 }, Counting { n: n + 1 })\n    } init Quiescent { }\n  frames = match state { Quiescent => 0, Counting { n: n } => n }\n  edge = (trigger > 0.5) * (prev_trigger <= 0.5)\n}",
  "VCA": "program VCA(audio: float = 0, cv: float = 0) -> (out: float) {\n  out = audio * cv\n}",
  "WhiteNoise": "program WhiteNoise() -> (out: float) {\n  reg state: int = 88172645463325250\n  out = let { s1: state ^ state << 13 } in\n    let { s2: s1 ^ s1 >> 7 } in\n    let { s3: s2 ^ s2 << 17 } in (s3 & 65535) * 2 / 65535 - 1\n  next state = let { s1: state ^ state << 13 } in\n    let { s2: s1 ^ s1 >> 7 } in s2 ^ s2 << 17\n}"
